import java.nio.charset.StandardCharsets;
import java.util.concurrent.Semaphore;
import java.util.concurrent.atomic.AtomicInteger;

public class mandelbrot {
    private static final int MAX_ITERATIONS = 50;

    public static void main(String[] args) throws Exception {
        final int n = Integer.parseInt(args[0]);
        final int rowBytes = n / 8 + ((n & 7) == 0 ? 0 : 1);

        final double[] real = new double[n];
        for (int x = 0; x < n; x++) {
            real[x] = 2.0 * x / n - 1.5;
        }

        final byte[][] rows = new byte[n][];
        final Object rowMonitor = new Object();
        final AtomicInteger nextRow = new AtomicInteger();

        int threadCount = Math.min(
                n,
                Math.min(32, Math.max(1, Runtime.getRuntime().availableProcessors()))
        );

        final Semaphore pendingSlots = new Semaphore(Math.max(1, threadCount * 2));
        Thread[] workers = new Thread[threadCount];

        for (int i = 0; i < threadCount; i++) {
            workers[i] = new Thread(() -> {
                try {
                    while (true) {
                        pendingSlots.acquire();

                        int y = nextRow.getAndIncrement();
                        if (y >= n) {
                            pendingSlots.release();
                            return;
                        }

                        byte[] row = renderRow(y, n, rowBytes, real);

                        synchronized (rowMonitor) {
                            rows[y] = row;
                            rowMonitor.notifyAll();
                        }
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
            workers[i].setDaemon(true);
            workers[i].start();
        }

        try (BufferedOutputStream out = new BufferedOutputStream(System.out, 65536)) {
            String header = "P4\n" + n + " " + n + "\n";
            out.write(header.getBytes(StandardCharsets.US_ASCII));

