                byte[] row;
                synchronized (rowMonitor) {
                    while ((row = rows[y]) == null) {
                        rowMonitor.wait();
                    }
                    rows[y] = null;
                }

                out.write(row);
                pendingSlots.release();
            }

            out.flush();
        }

        for (Thread worker : workers) {
            worker.join();
        }
    }

    private static byte[] renderRow(int y, int n, int rowBytes, double[] real) {
        byte[] row = new byte[rowBytes];
        double ci = 2.0 * y / n - 1.0;

        int x = 0;
